 clearTimeout(advanceTimer);
 const q=questions[step];
 $('step-label').textContent=`QUESTION ${step+1} OF ${questions.length}`; $('step-caption').textContent=q.caption;
 $('progress-fill').style.width=`${(step+1)/questions.length*100}%`; root.querySelector('.progress').setAttribute('aria-valuenow',step+1);
